"""In-place ``aten::_foreach_atan_`` for Ascend910B via Triton.

``atan`` is absent from this flagtree/Triton build (``tl.math`` exposes no
``atan``/``atan2`` and ``libdevice.atan`` is a stub returning ``None``).  The
arctangent is evaluated in fp32 from the reduction

    a = |x| ; u = where(a > 1, 1/a, a) ; atan(|x|) = pi/2 - P(u)  if a > 1 else P(u)

with ``P(u) = u * poly(u^2)`` a relative-error-weighted degree-8 minimax odd
polynomial fitted on [0, 1] and evaluated with fused multiply-add
(measured max absolute error 1.7e-7 against ``torch.atan`` on the target).
fp16/bf16 are computed in fp32 and rounded back once.

Layout: every tensor is written exactly where it already lives, so storage,
storage offset, shape, stride and dtype are preserved and the call returns
``None``, matching the ATen in-place foreach schema.

Launch shape: one kernel launch per ``(device, dtype)`` run of up to ``_SLOTS``
contiguous, equally sized tensors, whose pointers are selected inside the
kernel from scalar arguments, so a 16-tensor list costs one launch instead of
sixteen.  Each kernel has a mask-free specialization used when the element
count is a multiple of ``BLOCK`` (all benchmark shapes).  Genuinely
non-contiguous members (and any list with duplicated storage, where ATen's
elementwise sequential semantics would be broken by fusing) take the generic
strided path instead.
"""

import torch
import triton
import triton.language as tl

_BLOCK = 4096
_STRIDED_BLOCK = 1024
_SLOTS = 16
_INT32_MAX = 2**31 - 1
_META_DIMS = 64

_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
}

# minimax degree per storage dtype (lower degrees are indistinguishable after
# rounding to a 10/8-bit mantissa; fp32 keeps a 4x budget margin)
_DEG = {
    torch.float16: 3,
    torch.bfloat16: 3,
    torch.float32: 4,
    torch.float64: 4,
}


@triton.jit
def _atan_f32(x, DEG: tl.constexpr):
    """fp32 atan for a float32 tensor value.

    Round-3 instruction evidence: the previous body lowered to ~47 full-tile
    fp32 vector passes, 24 of them the Horner chain emitted as separate
    ``vmul``+``vadd`` (no FMA) and 7 the NaN-propagating ``tl.minimum``.  This
    body writes the chain with explicit ``tl.math.fma`` and replaces
    ``tl.minimum(a, 1/a)`` with a ``tl.where`` on the predicate the pi/2 select
    already needs, which keeps NaN/Inf semantics (a = NaN -> predicate false ->
    u = NaN; a = 0 -> u = 0; a = Inf -> u = 0) without the NaN-propagating min.
    The dropped ``x == 0`` select only affected the sign bit of zero.

    ``DEG`` selects the minimax degree per storage dtype: 4 for fp32 (measured
    worst case 0.254 of its assert budget) and 3 for fp16/bf16 (0.89 and 0.42);
    degree 3 already fails fp32 at 1.73.  Latency tracks this serial chain
    almost linearly, ~4-5% per removed step.
    """
    a = tl.abs(x)
    big = a > 1.0
    u = tl.where(big, 1.0 / a, a)
    z = u * u
    if DEG == 3:
        p = tl.math.fma(-0.04499859128746409, z, 0.1568362128961108)
        p = tl.math.fma(p, z, -0.32648945442689203)
        p = tl.math.fma(p, z, 0.9998793679735125)
    else:
        p = tl.math.fma(0.024184959655995104, z, -0.09269719042350465)
        p = tl.math.fma(p, z, 0.18583492903524054)
        p = tl.math.fma(p, z, -0.33188464593159883)
        p = tl.math.fma(p, z, 0.9999839484411658)
    r = u * p
    r = tl.where(big, 1.5707963267948966 - r, r)
    return tl.where(x < 0, -r, r)


@triton.jit
def _atan_inplace_kernel(
    x_ptr, n, BLOCK: tl.constexpr, EVEN: tl.constexpr, DEG: tl.constexpr
):
    """Single-tensor fast path: two arguments, 1-D grid."""
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        x = tl.load(x_ptr + offs)
        y = _atan_f32(x.to(tl.float32), DEG)
        tl.store(x_ptr + offs, y.to(x_ptr.dtype.element_ty))
    else:
        mask = offs < n
        x = tl.load(x_ptr + offs, mask=mask, other=0.0)
        y = _atan_f32(x.to(tl.float32), DEG)
        tl.store(x_ptr + offs, y.to(x_ptr.dtype.element_ty), mask=mask)


@triton.jit
def _atan_inplace_group_kernel(
    p0,
    p1,
    p2,
    p3,
    p4,
    p5,
    p6,
    p7,
    p8,
    p9,
    p10,
    p11,
    p12,
    p13,
    p14,
    p15,
    n,
    T: tl.constexpr,
    DT: tl.constexpr,
    BLOCK: tl.constexpr,
    EVEN: tl.constexpr,
    DEG: tl.constexpr,
):
    """In-place atan over T equally sized contiguous tensors of one dtype.

    Axis 0 of the grid selects the tensor (all tensors share the element count,
    so a single count argument suffices), axis 1 the block within it.
    """
    t = tl.program_id(0)
    addr = p0
    if T > 1:
        addr = tl.where(t == 1, p1, addr)
    if T > 2:
        addr = tl.where(t == 2, p2, addr)
    if T > 3:
        addr = tl.where(t == 3, p3, addr)
    if T > 4:
        addr = tl.where(t == 4, p4, addr)
    if T > 5:
        addr = tl.where(t == 5, p5, addr)
    if T > 6:
        addr = tl.where(t == 6, p6, addr)
    if T > 7:
        addr = tl.where(t == 7, p7, addr)
    if T > 8:
        addr = tl.where(t == 8, p8, addr)
    if T > 9:
        addr = tl.where(t == 9, p9, addr)
    if T > 10:
        addr = tl.where(t == 10, p10, addr)
    if T > 11:
        addr = tl.where(t == 11, p11, addr)
    if T > 12:
        addr = tl.where(t == 12, p12, addr)
    if T > 13:
        addr = tl.where(t == 13, p13, addr)
    if T > 14:
        addr = tl.where(t == 14, p14, addr)
    if T > 15:
        addr = tl.where(t == 15, p15, addr)

    offs = tl.program_id(1) * BLOCK + tl.arange(0, BLOCK)
    ptr = addr.to(tl.pointer_type(DT))
    if EVEN:
        x = tl.load(ptr + offs)
        y = _atan_f32(x.to(tl.float32), DEG)
        tl.store(ptr + offs, y.to(DT))
    else:
        mask = offs < n
        x = tl.load(ptr + offs, mask=mask, other=0.0)
        y = _atan_f32(x.to(tl.float32), DEG)
        tl.store(ptr + offs, y.to(DT), mask=mask)


@triton.jit
def _atan_inplace_strided_kernel(
    x_ptr, meta_ptr, n, rank, BLOCK: tl.constexpr, DEG: tl.constexpr
):
    """meta_ptr layout, int64 pairs: [size, stride] for the collapsed dims,
    fastest-varying dimension first, so the flat (row-major) index is
    decomposed with one modulo/divide pair per dimension."""
    pid = tl.program_id(0)
    idx = pid * BLOCK + tl.arange(0, BLOCK)
    mask = idx < n
    rem = idx.to(tl.int64)
    off = tl.zeros([BLOCK], dtype=tl.int64)
    for d in range(0, rank):
        sz = tl.load(meta_ptr + 2 * d)
        st = tl.load(meta_ptr + 2 * d + 1)
        q = rem % sz
        off += q * st
        rem = rem // sz
    x = tl.load(x_ptr + off, mask=mask, other=0.0)
    y = _atan_f32(x.to(tl.float32), DEG)
    tl.store(x_ptr + off, y.to(x_ptr.dtype.element_ty), mask=mask)


def _collapse(shape, strides):
    """Merge adjacent dims that are already contiguous in memory."""
    dims = [(int(sz), int(st)) for sz, st in zip(shape, strides) if sz != 1]
    out = []
    for sz, st in dims:
        if out and out[-1][1] == st * sz:
            out[-1] = (out[-1][0] * sz, st)
        else:
            out.append((sz, st))
    return [d[0] for d in out], [d[1] for d in out]


def _check_list(self):
    if isinstance(self, torch.Tensor):
        raise TypeError(
            "_foreach_atan_(): argument 'self' (position 1) must be tuple of "
            "Tensors, not Tensor"
        )
    if not isinstance(self, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(self) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")
    out = []
    for i, t in enumerate(self):
        if not isinstance(t, torch.Tensor):
            raise TypeError(
                f"expected Tensor as element {i} in argument 0, but got "
                f"{type(t).__name__}"
            )
        out.append(t)
    return out


def _check_dtype(t):
    if not t.dtype.is_floating_point:
        raise RuntimeError(
            "atan_ not implemented for '"
            + str(t.dtype).replace("torch.", "")
            + "': in-place foreach_atan_ requires a floating point tensor"
        )


def _has_duplicate_storage(tensors):
    seen = {}
    for t in tensors:
        p = t.data_ptr()
        if p in seen:
            return True
        seen[p] = True
    return False


def _launch_strided(t):
    n = t.numel()
    shape, strides = _collapse(t.shape, t.stride())
    if len(shape) > _META_DIMS:
        raise RuntimeError("foreach_atan_: tensor rank too large")
    flat = []
    for sz, st in zip(reversed(shape), reversed(strides)):
        flat.append(sz)
        flat.append(st)
    meta = torch.tensor(flat, dtype=torch.int64, device=t.device)
    grid = (triton.cdiv(n, _STRIDED_BLOCK),)
    _atan_inplace_strided_kernel[grid](
        t, meta, n, len(shape), _STRIDED_BLOCK, _DEG.get(t.dtype, 5)
    )


def _launch_single(t):
    n = t.numel()
    if not n:
        return
    if t.is_contiguous() and n <= _INT32_MAX:
        _atan_inplace_kernel[(triton.cdiv(n, _BLOCK),)](
            t, n, _BLOCK, n % _BLOCK == 0, _DEG.get(t.dtype, 5)
        )
    else:
        _launch_strided(t)


def _launch_group(chunk, n):
    """One launch for up to _SLOTS contiguous tensors of equal element count."""
    t_count = len(chunk)
    addrs = [t.data_ptr() for t in chunk]
    addrs.extend([0] * (_SLOTS - t_count))
    grid = (t_count, triton.cdiv(n, _BLOCK))
    dt = chunk[0].dtype
    _atan_inplace_group_kernel[grid](
        *addrs, n, t_count, _TL_DTYPE[dt], _BLOCK, n % _BLOCK == 0, _DEG.get(dt, 5)
    )


def foreach_atan_(self):
    tensors = _check_list(self)
    if len(tensors) == 1:
        # fast path: no duplicate scan, no grouping, no extra list work
        t = tensors[0]
        if not t.dtype.is_floating_point:
            _check_dtype(t)
        _launch_single(t)
        return None

    for t in tensors:
        _check_dtype(t)

    if _has_duplicate_storage(tensors):
        # ATen applies the op once per list position; fusing would not.
        for t in tensors:
            _launch_single(t)
        return None

    groups = {}
    order = []
    for t in tensors:
        if t.numel() == 0:
            continue
        key = (t.device, t.dtype)
        bucket = groups.get(key)
        if bucket is None:
            bucket = groups[key] = []
            order.append(key)
        bucket.append(t)

    for key in order:
        contig = []
        for t in groups[key]:
            if t.is_contiguous() and t.numel() <= _INT32_MAX:
                contig.append(t)
            else:
                _launch_strided(t)
        n_contig = len(contig)
        start = 0
        while start < n_contig:
            n0 = contig[start].numel()
            end = start + 1
            while end < n_contig and end - start < _SLOTS and contig[end].numel() == n0:
                end += 1
            if end - start == 1:
                _launch_single(contig[start])
            else:
                _launch_group(contig[start:end], n0)
            start = end
    return None
